#!/bin/bash
set -euo pipefail

# code-node-example - Generated by flowsh
# Registry-based workflow execution script

echo "Starting workflow: code-node-example"

# Workflow variables and state management
declare -A workflow_vars
declare -A workflow_state

# Color codes for output
RED='\033[0;31m'
GREEN='\033[0;32m'
YELLOW='\033[1;33m'
BLUE='\033[0;34m'
CYAN='\033[0;36m'
NC='\033[0m'

# Configuration
VERBOSE=${VERBOSE:-false}
AGENT_TIMEOUT=${AGENT_TIMEOUT:-60}

# Environment Variables
TARGET_DIRECTORY=${TARGET_DIRECTORY:-""}
FILE_PATTERN=${FILE_PATTERN:-""}

# =============================================================================
# UTILITY FUNCTIONS
# =============================================================================

# Logging functions with colors
log_info() {
    echo -e "${CYAN}ℹ️  $*${NC}"
}

log_success() {
    echo -e "${GREEN}✅ $*${NC}"
}

log_error() {
    echo -e "${RED}❌ $*${NC}" >&2
}

log_warning() {
    echo -e "${YELLOW}⚠️  $*${NC}" >&2
}

log_debug() {
    [[ "$VERBOSE" == "true" ]] && echo -e "${BLUE}🔍 DEBUG: $*${NC}" >&2 || true
}

log_step() {
    echo -e "${CYAN}🚀 $*${NC}"
}

# Operation logging with correlation IDs
log_operation_start() {
    local operation_name="$1"
    local operation_type="$2"
    local correlation_id="$3"
    log_debug "$correlation_id" "Starting $operation_type: $operation_name"
}

log_operation_end() {
    local operation_name="$1"
    local operation_type="$2"
    local correlation_id="$3"
    local status="${4:-success}"
    log_debug "$correlation_id" "Completed $operation_type: $operation_name ($status)"
}

# Enhanced error handling
handle_error() {
    local exit_code=$1
    local context="$2"
    local node_id="${3:-unknown}"
    
    case $exit_code in
        124)
            log_error "Timeout: $context took longer than ${AGENT_TIMEOUT}s (node: $node_id)"
            ;;
        127)
            log_error "Command not found in: $context (node: $node_id)"
            ;;
        1)
            log_error "General error in: $context (node: $node_id)"
            ;;
        *)
            log_error "Unknown error (exit code $exit_code) in: $context (node: $node_id)"
            ;;
    esac
    
    return $exit_code
}

# Variable management
set_workflow_var() {
    local var_name="$1"
    local var_value="$2"
    workflow_vars["$var_name"]="$var_value"
    log_debug "Set variable: $var_name = $var_value"
}

get_workflow_var() {
    local var_name="$1"
    local default_value="${2:-}"
    echo "${workflow_vars[$var_name]:-$default_value}"
}

# State management
set_workflow_state() {
    local state_key="$1"
    local state_value="$2"
    workflow_state["$state_key"]="$state_value"
    log_debug "Set state: $state_key = $state_value"
}

get_workflow_state() {
    local state_key="$1"
    local default_value="${2:-}"
    echo "${workflow_state[$state_key]:-$default_value}"
}

# Variable substitution in templates
substitute_variables() {
    local template="$1"
    local result="$template"
    
    # Find all variable references in the format {{#variable_name#}}
    while [[ $result =~ \{\{#([^#]+)#\}\} ]]; do
        local var_ref="${BASH_REMATCH[1]}"
        local var_value=$(get_workflow_var "$var_ref" "")
        
        if [[ -z "$var_value" ]]; then
            log_warning "Variable reference '$var_ref' not found, using empty string"
        fi
        
        # Escape special characters for sed
        local escaped_value=$(printf '%s\n' "$var_value" | sed 's/[[\.\*^\$()+?{|]/\\&/g')
        result=$(echo "$result" | sed "s|{{#${var_ref}#}}|$escaped_value|g")
    done
    
    echo "$result"
}

# Workflow Execution

# Node: create_workspace
mkdir

# Node: list_files
find

# Node: count_lines
sh

# Node: get_file_sizes
sh

# Node: create_summary
sh

# Node: read_summary
cat

# Node: cleanup_workspace
rm

# Node: success_summary
echo "# 🔧 Code Node Example Completed Successfully!

## Executed Operations:

1. **Workspace Creation** ✅
   - Created temporary workspace at `/tmp/flowsh-code-example`
   - Set environment variables for tracking

2. **File Discovery** 📁
   - Searched for pattern: `${file_pattern}`
   - Target directory: `${target_directory}`

3. **Analysis Operations** 📊
   - Counted lines in matched files
   - Calculated total file sizes
   - Generated summary report

4. **Cleanup** 🧹
   - Removed temporary workspace
   - All operations completed safely

## Code Node Features Demonstrated:

- **Command Execution**: Various shell commands (mkdir, find, wc, du, cat, rm)
- **Argument Passing**: Dynamic arguments with variable interpolation
- **Working Directory**: Different working directories for different operations
- **Environment Variables**: Custom environment setup
- **Timeout Management**: Appropriate timeouts for different operations
- **Error Handling**: Safe operations with proper cleanup

This example shows how code nodes can execute complex shell operations while maintaining safety and proper resource management.
"

echo "Workflow completed successfully"
exit 0
